SELECT (COUNT(CASE WHEN jobs.job_desc IN ('Editor', 'Designer') THEN 1 END) * 100.0 / COUNT(*)) AS percentage
FROM employee
JOIN jobs ON employee.job_id = jobs.job_id;

SELECT MAX(job_lvl)
FROM employee
WHERE hire_date = (SELECT MIN(hire_date) FROM employee);

SELECT COUNT(*) AS num_sales
FROM sales
WHERE stor_id = (SELECT stor_id FROM stores WHERE city = 'Remulade');

SELECT SUM(CASE WHEN category_name = 'Buffets' THEN 1 ELSE 0 END) - SUM(CASE WHEN category_name = 'Gyms' THEN 1 ELSE 0 END) AS difference
FROM Business_Categories
JOIN Categories ON Business_Categories.category_id = Categories.category_id;

SELECT attribute_id
FROM Attributes
WHERE attribute_name LIKE '%payment%';

SELECT review_length
FROM Reviews
WHERE business_id = 2 AND user_id = 35026;

SELECT COUNT(*) AS num_swimming_events
FROM event
WHERE sport_id = (SELECT id FROM sport WHERE sport_name = 'Swimming');
